/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args    _args)
{
    AVAKBVSearchQueryBuild      searchQueryBuild = new AVAKBVSearchQueryBuild();
    if (_args.caller() is FormRun)
    {
        searchQueryBuild.parmCallerFormRun(_args.caller());
    }

    searchQueryBuild.run();

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_callerFormRun">_callerFormRun</param>
/// <returns>formRun</returns>
FormRun parmCallerFormRun(FormRun       _callerFormRun = callerFormRun)
{
    callerFormRun  = _callerFormRun;
    return callerFormRun;
}

/// <summary>
/// designed from AVA
/// </summary>
public void run()
{
    FormDataSource          searchTable_ds = callerFormRun.dataSource(formDataSourceStr(AVAKBVBuildingProjectSearch,KCS_KBVSearchTable));
    FormDataSource          buildingProject_ds = callerFormRun.dataSource(formDataSourceStr(AVAKBVBuildingProjectSearch,KCS_KBVBuildingProjectTable));

    if (formHasMethod(callerFormRun,'buildQueryRanges'))
    {
        callerFormRun.buildQueryRanges();
    }

    if (formHasMethod(callerFormRun,'buildQuery'))
    {
        callerFormRun.buildQuery();
    }

    searchTable_ds.executeQuery();
    buildingProject_ds.executeQuery();
}
